_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "a > b": full reward; "a == b >= 1": reward / 2 each;\n# "a == b == 0": the order stays open.\n# Cost: "upkeep_i = UPKEEP * (UNITS_PER_PLAYER - units_i at own base)".\n# Orders pay once, not once per remaining turn. Majority payouts are not\n# concave, so contested nodes are evaluated as complete tie/win bundles.\n\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nUPKEEP = 1.0\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for row in adjacency:\n        row.sort()\n    distances = []\n    for start in range(n):\n        row = [-1] * n\n        row[start] = 0\n        queue = deque([start])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] < 0:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source != target and distances[source][target] > 0:\n                next_hop[source][target] = next(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef payout(own, opponent, reward):\n    if own > opponent:\n        return float(reward), 0.0\n    if opponent > own:\n        return 0.0, float(reward)\n    if own > 0:\n        return float(reward) / 2.0, float(reward) / 2.0\n    return 0.0, 0.0\n\n\ndef additional_trip_cost(source, target, base, distance, horizon):\n    """Full travel, service, and return upkeep, relative to returning now.\n\n    Returning d edges home costs d-1 paid turns: the final move is free.\n    Holding at the service node this turn counts as one service turn.\n    At the end of the game no subsequent return costs are charged.\n    """\n    arrival = max(1, distance[source][target])\n    trip = min(horizon, arrival + distance[target][base] - 1)\n    home = min(horizon, max(0, distance[source][base] - 1))\n    return UPKEEP * (trip - home)\n\n\ndef build_plan(obs, distances, previous_targets, deadline):\n    n = int(obs["n_nodes"])\n    base = int(obs["player_base"])\n    own = list(obs["player_units"])\n    opponent = obs["opponent_units"]\n    horizon = max(0, N_TURNS - int(obs["turn"]))\n    remaining = own[:]\n    wanted = [0] * n\n    orders = [[] for _ in range(n)]\n    for node, reward, left in obs.get("orders", []):\n        orders[node].append((float(reward), min(int(left), horizon)))\n\n    # Spare units always have the cost-free home as their ultimate destination.\n    # A node with visible opposition will be resolved this turn under the\n    # stationary-opponent model; a later arrival cannot collect its orders.\n    candidates = [v for v in range(n) if orders[v] and v != base]\n    while candidates and time.perf_counter() < deadline:\n        best = None\n        for target in candidates:\n            if time.perf_counter() >= deadline:\n                break\n            enemy = int(opponent[target])\n            sizes = [1] if enemy == 0 else [enemy, enemy + 1]\n            sources = []\n            for source in range(n):\n                d = distances[source][target]\n                if remaining[source] <= 0 or d < 0:\n                    continue\n                arrival = max(1, d)\n                if enemy and arrival > 1:\n                    continue\n                if not any(left >= arrival for _, left in orders[target]):\n                    continue\n                cost = additional_trip_cost(\n                    source, target, base, distances, horizon\n                )\n                # Nearer units are preferable when costs are equal.\n                sources.extend(\n                    (cost, arrival, source)\n                    for _ in range(remaining[source])\n                )\n            sources.sort()\n            for size in sizes:\n                if size <= 0 or len(sources) < size:\n                    continue\n                # With no opponent only one unit is necessary. With an\n                # opponent all selected units can arrive this turn.\n                chosen = sources[:size]\n                arrival = max(item[1] for item in chosen)\n                reward = sum(r for r, left in orders[target] if left >= arrival)\n                if reward <= 0:\n                    continue\n                mine, theirs = payout(size, enemy, reward)\n                baseline_mine, baseline_theirs = payout(0, enemy, reward)\n                gain = (mine - theirs) - (baseline_mine - baseline_theirs)\n                net = gain - sum(item[0] for item in chosen)\n                if net <= 0.25:\n                    continue\n                # Small commitment bonus prevents near-equal routes flipping.\n                sticky = 0.55 if previous_targets.get(target, 0) else 0.0\n                merit = (net + sticky) / (1.0 + 0.22 * (arrival - 1))\n                key = (merit, net, -arrival, -size, -target)\n                if best is None or key > best[0]:\n                    best = (key, target, chosen)\n        if best is None:\n            break\n        _, target, chosen = best\n        for _, _, source in chosen:\n            remaining[source] -= 1\n            wanted[target] += 1\n        candidates.remove(target)\n\n    wanted[base] += sum(remaining)\n    return wanted\n\n\ndef legal_action(have, wanted, adjacency, distances, next_hop):\n    """Closest-first surplus matching, then independent start-state validation."""\n    n = len(have)\n    surplus = [max(0, have[v] - wanted[v]) for v in range(n)]\n    deficit = [max(0, wanted[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    combined = {}\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        hop = next_hop[source][target]\n        if hop < 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        key = (source, hop)\n        combined[key] = combined.get(key, 0) + count\n\n    available = list(have)\n    action = []\n    for (source, target), requested in sorted(combined.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if source == target or target not in adjacency[source]:\n            continue\n        count = min(int(requested), int(available[source]))\n        if count <= 0:\n            continue\n        available[source] -= count\n        action.append((int(source), int(target), int(count)))\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.adjacency = None\n        self.distances = None\n        self.next_hop = None\n        self.previous_targets = {}\n        self.bad_turns = 0\n        self.conservative = False\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        key = (n, tuple(tuple(e) for e in obs["edges"]))\n        if key != self.map_key:\n            self.adjacency, self.distances, self.next_hop = preprocess_map(\n                n, obs["edges"]\n            )\n            self.map_key = key\n            self.previous_targets = {}\n\n        bad = (\n            not obs.get("action_format_correct_last_turn", True)\n            or obs.get("n_invalid_actions_last_turn", 0) > 0\n        )\n        self.bad_turns = self.bad_turns + 1 if bad else 0\n        if self.bad_turns >= 2:\n            self.conservative = True\n\n        have = list(obs["player_units"])\n        base = int(obs["player_base"])\n        if self.conservative:\n            # Simple independent one-hop recalls after repeated error feedback.\n            action = []\n            for source in range(n):\n                if source != base and have[source] > 0:\n                    hop = self.next_hop[source][base]\n                    if hop in self.adjacency[source]:\n                        action.append((int(source), int(hop), int(have[source])))\n            return action\n\n        wanted = build_plan(\n            obs, self.distances, self.previous_targets, deadline\n        )\n        action = legal_action(\n            have, wanted, self.adjacency, self.distances, self.next_hop\n        )\n        self.previous_targets = {\n            v: int(wanted[v]) for v in range(n) if v != base and wanted[v] > 0\n        }\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
